/**
 * self is the window to be centered or the whole screen if parent is nullptr
 * parent: The window self will be centered relative to. Optional
 * w: the width of the self
 * h: the height of self
 */
auto center(Fl_Window* self, Fl_Window* parent, int w, int h) -> Fl_Window*
{
    auto max_x = parent == nullptr ? Fl::w() : parent->w();
    auto max_y = parent == nullptr ? Fl::h() : parent->h();

    auto px = parent == nullptr ? 0 : parent->x();
    auto py = parent == nullptr ? 0 : parent->y();

    auto x = px + (max_x / 2) - (w / 2);
    auto y = py + (max_y / 2) - (h / 2);

    assert(x > 0);
    assert(x < Fl::w());
    assert(y > 0);
    assert(y < Fl::h());

    self->resize(x, y, w, h);
    return self;
}

/**
 * self is the window to be centered
 * parent is optional. self will be centered relative to the parent or the whole
 * screen if parent is nullptr
 */
auto center(Fl_Window* self, Fl_Window* parent) -> Fl_Window*
{
    return center(self, parent, self->w(), self->h());
}

auto center(Fl_Window* self) -> Fl_Window*
{
    return center(self, nullptr, self->w(), self->h());
}

static void relabel_hash_parent(Fl_Tree_Item* item)
{
    if (!item || !item->label()) {
        ::output("Unexpected null item! Application will terminate!");
        die();
    }
    // re-make the label for this hash to reflect the removed files
    std::string label = item->label();
    auto        pos   = std::find(label.begin(), label.end(), '(');
    if (pos == label.end()) {
        ::output(
            "Hash parent relabel does not match expected string. Application "
            "will terminate!");
        die();
    }
    label.erase(pos, label.end());
    label.insert(label.size(), std::format("({} files)", item->children()));
    // FLTK's Fl_Tree_Item::label() copies the string internally
    item->label(label.c_str());
}

